public int[] calculateProduct(int[] nums) {
    int n = nums.length;
    int[] output = new int[n];

    // Calculate the product of all elements to the left of index i
    int leftProduct = 1;
    for (int i = 0; i < n; i++) {
        output[i] = leftProduct;
        leftProduct *= nums[i];
    }

    // Calculate the product of all elements to the right of index i and multiply with the left product
    int rightProduct = 1;
    for (int i = n - 1; i >= 0; i--) {
        output[i] *= rightProduct;
        rightProduct *= nums[i];
    }

    return output;
}

